/**
 * The application's text, and the loader that decides how much of it is in memory.
 *
 * **English is compiled in; every other language is fetched.** English is not merely the default
 * (`languageStore`) — it is the per-key fallback in `render`, so a lookup has to be able to reach it
 * synchronously, always. Spanish has no such requirement, and keeping it here cost every English
 * session ~325 KB of string literals parsed at startup and held for the life of the process to
 * translate nothing. It now lives in `translations.es.ts` behind a dynamic import.
 *
 * The trade is one await, and it is paid where it is invisible: `languageStore.init()` and
 * `setLanguage()` both load the dictionary *before* flipping `language`, so `useT`'s memoised
 * closure (see the note there) can never be handed a half-filled dictionary and no string ever
 * renders in one language and then swaps to the other. A Spanish user's first frame was already
 * English — `App` initialises the language from an effect after the first render — so nothing about
 * what is on screen changes.
 *
 * `es` starts as an empty object rather than `undefined` on purpose: `render` reads
 * `translations[language][key] ?? translations.en[key]`, and the two synchronous callers that can
 * run before the load lands (`translate`, and `apiStore`'s error mapping) then degrade to English
 * instead of throwing.
 */

