  "settings.reviewStandardTitle": "PR review standard",
  "settings.reviewStandardTitleForProject": "PR review standard — {name}",
  "settings.reviewStandardSelectWorkspace": "Select a workspace to edit its review standard.",
  "settings.reviewStandardHint":
    "The base methodology every PR review in this workspace runs under (SonarQube-style taxonomy, A–E ratings, Quality Gate, review lenses and output format). It's transversal — keep project-specific rules in \"PR review context\" / \"Instructions\", not here. Editing it changes how reviews are graded and reported.",
  "settings.reviewStandardPlaceholder": "The review methodology the AI follows for every PR in this workspace…",
  "settings.reviewStandardResetConfirm": "Restore this workspace's review standard to the built-in default? Your edits will be lost.",

  "settings.reviewHint":
    "What Claude reads before reviewing a pull request in this workspace: the review methodology, the context it is given, and the memories it has kept.",
  "settings.reviewTitleForProject": "PR review — {name}",
  "settings.reviewSelectWorkspace": "Select a workspace to configure its PR review.",
  "settings.reviewTabStandard": "Standard",
  "settings.reviewTabEngine": "Engine",
  "settings.engineHint":
    "The numbers a review is actually held to. Unlike the prompts, these are enforced in code — the threshold decides which findings survive, the severities decide what is even looked for, and all of it is frozen into every saved review so an old one still says which rules produced it.",
  "settings.engineLevel": "Level",
  "settings.engineMinConfidence": "Confidence threshold",
  "settings.engineMinConfidenceHint": "A finding below this is dropped, with the reason logged.",
  "settings.engineMinConfidenceBlocker": "Blocker threshold",
  "settings.engineMinConfidenceBlockerHint": "Lower on purpose: staying quiet about a possible data loss costs more than a false positive.",
  "settings.engineSeverities": "Reported severities",
  "settings.engineSeveritiesHint": "Independent of the threshold — a Minor at confidence 100 still won't survive a level that doesn't report Minor.",
  "settings.engineLenses": "Active lenses",
  "settings.engineLensesHint": "They travel in each reviewer's bundle. Edit their wording in Prompt templates → PR review.",
  "settings.engineSubagents": "Parallel reviewers",
  "settings.engineSubagentsHint": "Split the files across several reviewers. Faster and more thorough — and several times the tokens.",
  "settings.engineCrossFile": "Cross-file pass",
  "settings.engineCrossFileHint": "One extra pass over the outline alone, for breaking changes no single-file reviewer can see.",
  "settings.engineFilesPerGroup": "Files per reviewer",
  "settings.engineFilesPerGroupHint": "Fewer files means each one is read more deeply.",
  "settings.engineMaxGroups": "Max reviewers",
  "settings.engineMaxGroupsHint": "Ceiling, so a 300-file PR doesn't open 60 of them.",
  "settings.engineGate": "Quality Gate",
  "settings.engineGateHint": "Severities that make the gate FAIL. If one of them isn't reported by a level, that level's PASSED is flagged as inconclusive rather than trusted.",
  "settings.engineScope": "Scope",
  "settings.engineScopeHint": "Applied before anything is read, so what's out of scope never reaches a prompt or a token budget.",
  "settings.engineInclude": "Include",
  "settings.engineIncludeHint": "One glob per line. Empty means everything.",
  "settings.engineExclude": "Exclude",
  "settings.engineExcludeHint": "One glob per line. A bare filename matches at any depth.",
  "settings.engineContext": "Reading budget",
  "settings.engineContextHint": "How much code each reviewer is handed. What's trimmed is stated in the review, and the model can still open the file itself.",
  "settings.engineContextLines": "Context lines",
  "settings.engineContextLinesHint": "Padding around each touched symbol.",
  "settings.engineMaxLines": "Max lines per file",
  "settings.engineMaxLinesHint": "Past it, untouched ranges are dropped before changed ones.",
  "settings.engineMaxKb": "Max KB per reviewer",
  "settings.engineMaxKbHint": "Past it, the least-changed files degrade to a stub naming their symbols.",
  "settings.engineWorkers": "Parallelism",
  "settings.engineWorkersHint": "Each reviewer is a full model run, so this caps cost and rate limits, not CPU.",
  "settings.engineMaxParallel": "Reviewers at once",
  "settings.engineMaxParallelHint": "Groups beyond this wait their turn.",
  "settings.engineGraph": "Impact outside the PR",
  "settings.engineGraphHint": "Who else in the repository references the symbols this PR touches — a hint for contract and signature changes. Read from the local clone; nothing is installed.",
  "settings.engineGraphEnabled": "Look for references",
  "settings.engineGraphEnabledHint": "Costs one sweep of the target branch per review.",
  "settings.engineGraphSymbols": "Max symbols",
  "settings.engineGraphCallers": "Max references per symbol",
  "settings.engineSaving": "Saving…",
  "settings.engineResetConfirm": "Restore the built-in review policy? Every level, gate, scope and budget override in this workspace is discarded.",
  "settings.prReviewPromptsTitle": "PR review",
  "settings.prReviewPromptsHint":
    "How a pull request is reviewed. The methodology lives in the Review section's Standard tab; these tune depth and split the work. The numbers come from the Engine tab through {{MIN_CONFIANZA}}-style placeholders, so editing the wording can never put the instruction and the filter that enforces it out of step.",
  "settings.prPromptLenses": "Review lenses",
  "settings.prPromptLensesHint":
    "One per line, numbered. Each level switches a subset on, and the selected ones travel in every reviewer's reading bundle.",
  "settings.prPromptLevelBasico": "Depth · Basic",
  "settings.prPromptLevelCompleto": "Depth · Full",
