export type Language = "en" | "es";
export type TranslationKey = keyof typeof en;

/** Every language's dictionary. Only English is guaranteed complete and present. */
export const translations: { en: Readonly<Record<TranslationKey, string>>; es: Partial<Record<TranslationKey, string>> } = {
  en,
  es: {},
};

/** In flight or done, so two callers (init and a fast setLanguage) load the file once. */
let esLoad: Promise<void> | null = null;

/**
 * Makes `translations[language]` real. Resolves immediately for English.
 *
 * A failed load is not cleared: retrying on every keystroke of a language switch would be worse
 * than the fallback, which is a fully working app in English.
 */
export function loadLanguage(language: Language): Promise<void> {
  if (language !== "es") return Promise.resolve();
  if (!esLoad) {
    esLoad = import("./translations.es")
      .then(({ es }) => {
        translations.es = es;
      })
      .catch(() => {});
  }
  return esLoad;
}
